\title{Radical Degree-Two Quotients of Montgomery Curves:\\Affine Correctness, Fibers, Normalization, and Action Laws}
\author{Aristotle}
\date{28 July 2026}

\begin{document}
\maketitle

\begin{abstract}
For the affine Montgomery curve $E_A:y^2=x^3+Ax^2+x$ over an arbitrary field and an input with $x\ne0$, we study the rational evaluation
\[
X=x+x^{-1},\qquad Y=y(1-x^{-2}).
\]
We prove that the image lies on $Y^2=X^3+AX^2-4X-4A$, whose cubic factors as $(X+A)(X-2)(X+2)$. The nonzero fibers are exact: $x+x^{-1}=z+z^{-1}$ precisely when $x=z$ or $xz=1$, and the complete output is invariant under $(x,y)\mapsto(x^{-1},-yx^{-2})$. If $r^2=B$, scaling $(x,y)\mapsto(x,ry)$ correctly normalizes $By^2=x^3+Ax^2+x$ and is injective for $r\ne0$, yielding an end-to-end normalize-then-quotient algorithm. Finally, for a free transitive action of a finite commutative group on curve classes, we establish composition, reversal, connector recovery, and uniqueness for labeled steps.
\end{abstract}

\section{Introduction}
Isogeny-based cryptography navigates networks of elliptic curves connected by algebraic maps. Reliable evaluation requires explicit formulas whose target equation, fibers, exceptional inputs, and composition behavior are understood. Montgomery coordinates make a degree-two quotient particularly transparent.

Let $K$ be a field and $A\in K$. We study
\[
E_A:\quad y^2=x^3+Ax^2+x=x(x^2+Ax+1).
\]
The point $(0,0)$ is visibly of order two whenever this cubic is a nonsingular elliptic curve. Away from $x=0$, the quotient formula is
\[
(x,y)\longmapsto\left(x+x^{-1},y(1-x^{-2})\right).
\]
The present treatment is affine and algebraic. No finiteness or nonsingularity assumption is needed for the identities. Geometric interpretations require the customary nonsingularity and characteristic hypotheses. This distinction makes clear both what is proved and what remains for a projective theory.

\section{Definitions}
\begin{definition}[Source and target equations]
The normalized Montgomery affine curve is
\[
E_A(K)=\{(x,y)\in K^2:y^2=x^3+Ax^2+x\}.
\]
The degree-two quotient equation is
\[
E_A^{(2)}(K)=\{(X,Y)\in K^2:Y^2=X^3+AX^2-4X-4A\}.
\]
\end{definition}

\begin{definition}[Degree-two evaluation and deck transformation]
For $x\ne0$, put
\[
\Phi_A(x,y)=\left(x+x^{-1},y(1-x^{-2})\right),\qquad
\iota(x,y)=\left(x^{-1},-yx^{-2}\right).
\]
\end{definition}

\begin{definition}[Radical normalization]
For $r\in K$, define $N_r(x,y)=(x,ry)$. When $r^2=B$, this relates the twisted equation $By^2=x^3+Ax^2+x$ to $E_A$.
\end{definition}

\section{Target factorization and affine correctness}
\begin{theorem}[Target factorization]
For all $A,X\in K$,
\[
X^3+AX^2-4X-4A=(X+A)(X-2)(X+2).
\]
\end{theorem}
\begin{proof}
Since $(X-2)(X+2)=X^2-4$, multiplication by $X+A$ gives the displayed polynomial.
\end{proof}

\begin{corollary}[Visible ordinate-zero points]
The points $(-A,0)$, $(2,0)$, and $(-2,0)$ satisfy $E_A^{(2)}$.
\end{corollary}
\begin{proof}
At each abscissa one factor of the target cubic vanishes.
\end{proof}

\begin{theorem}[Affine correctness]
Suppose $(x,y)\in E_A(K)$ and $x\ne0$. If
\[
X=x+x^{-1},\qquad Y=y(1-x^{-2}),
\]
then $(X,Y)\in E_A^{(2)}(K)$.
\end{theorem}
\begin{proof}
Substitution of the source equation gives
\[
Y^2=(x^3+Ax^2+x)(1-x^{-2})^2.
\]
After expansion, the terms independent of $A$ become
\[
x^3+3x+3x^{-1}+x^{-3}-4x-4x^{-1}
=(x+x^{-1})^3-4(x+x^{-1}),
\]
and the $A$-terms become
\[
A(x^2-2+x^{-2})=A(x+x^{-1})^2-4A.
\]
Putting $X=x+x^{-1}$ yields $Y^2=X^3+AX^2-4X-4A$.
\end{proof}

\begin{remark}
The condition $x\ne0$ is exactly the condition needed for affine inversion. The theorem does not by itself extend the rational formula across $(0,0)$ or identify a projective kernel.
\end{remark}

\section{Deck symmetry and exact fibers}
\begin{theorem}[Complete deck invariance]
For $x\ne0$,
\[
\Phi_A\left(x^{-1},-yx^{-2}\right)=\Phi_A(x,y).
\]
\end{theorem}
\begin{proof}
The first coordinate is unchanged because $x^{-1}+(x^{-1})^{-1}=x^{-1}+x$. For the second,
\[
(-yx^{-2})(1-(x^{-1})^{-2})=-yx^{-2}(1-x^2)=y(1-x^{-2}).
\]
\end{proof}

\begin{theorem}[Exact nonzero fibers]
For $x,z\in K^\times$,
\[
x+x^{-1}=z+z^{-1}
\quad\Longleftrightarrow\quad
x=z\ \text{or}\ xz=1.
\]
\end{theorem}
\begin{proof}
Clearing the nonzero denominator $xz$ and rearranging gives
\[
(x-z)(xz-1)=0.
\]
The absence of zero divisors proves the forward implication. Conversely, equality is immediate if $x=z$, while $xz=1$ gives $z=x^{-1}$ and reciprocal invariance.
\end{proof}

\begin{corollary}[Fiber sizes]
Every fiber of $x\mapsto x+x^{-1}$ on $K^\times$ has at most two elements. It is a singleton exactly when $x^2=1$; otherwise it is $\{x,x^{-1}\}$.
\end{corollary}
\begin{proof}
The theorem restricts the fiber to those two candidates, which coincide exactly at a fixed point of inversion.
\end{proof}

\section{Images of source torsion roots}
\begin{theorem}[Image of a nonzero quadratic root]
If $x\ne0$ and $x^2+Ax+1=0$, then $x+x^{-1}=-A$.
\end{theorem}
\begin{proof}
Divide by $x$ to obtain $x+A+x^{-1}=0$.
\end{proof}

\begin{corollary}
Whenever the two roots of $t^2+At+1$ exist and are distinct, they are reciprocal and their ordinate-zero source points both map to $(-A,0)$.
\end{corollary}
\begin{proof}
Their product is $1$, the preceding theorem gives their common image abscissa, and the output ordinate is zero.
\end{proof}

\section{Radical normalization}
\begin{theorem}[Correctness of normalization]
If $r^2=B$ and
\[
By^2=x^3+Ax^2+x,
\]
then $N_r(x,y)=(x,ry)$ lies on $E_A$.
\end{theorem}
\begin{proof}
One has $(ry)^2=r^2y^2=By^2=x^3+Ax^2+x$.
\end{proof}

\begin{theorem}[Injectivity]
If $r\ne0$, then $N_r:K^2\to K^2$ is injective.
\end{theorem}
\begin{proof}
Equality of normalized pairs gives equality of their first coordinates and $ry=rw$. Cancellation of nonzero $r$ gives $y=w$.
\end{proof}

\begin{theorem}[End-to-end radical quotient]
Assume
\[
r^2=B,\qquad By^2=x^3+Ax^2+x,\qquad x\ne0.
\]
Set
\[
X=x+x^{-1},\qquad Y=ry(1-x^{-2}).
\]
Then $(X,Y)\in E_A^{(2)}(K)$.
\end{theorem}
\begin{proof}
Normalization puts $(x,ry)$ on $E_A$, after which affine correctness applies.
\end{proof}

\section{Algorithms}
\subsection{Direct evaluation}
A direct evaluator performs the following steps:
\begin{enumerate}[label=\arabic*.]
\item Reject $x=0$ on the affine chart.
\item Compute $u=x^{-1}$.
\item Return $X=x+u$ and $Y=y(1-u^2)$.
\item Optionally validate $Y^2=X^3+AX^2-4X-4A$.
\end{enumerate}
This uses one inversion and a constant number of multiplications and additions, hence $O(1)$ field operations per point. Inversion normally dominates, and batch inversion can amortize it.

\subsection{Normalize then quotient}
For a twisted input and supplied $r$ with $r^2=B$, first compute $y'=ry$ and then apply direct evaluation to $(x,y')$. This adds one multiplication. Extracting $r$ is a separate finite-field square-root problem and is not included in the evaluation cost.

\subsection{Fiber classification}
For nonzero $x,z$, first test $x=z$, then test $xz=1$. The exact-fiber theorem proves that these tests decide whether the quotient abscissas agree, using one multiplication after the equality check.

\section{Free transitive action laws}
Let a finite commutative group $G$ act freely and transitively on a finite set $S$ of curve classes. Freeness means $a\cdot C=b\cdot C$ implies $a=b$; transitivity means every ordered pair of classes is connected by some group element.

\begin{definition}[Verified labeled step]
A label $a\in G$ verifies a step from $C$ to $D$ if $a\cdot C=D$.
\end{definition}

\begin{theorem}[Composition]
If $a\cdot C=D$ and $b\cdot D=E$, then $(ba)\cdot C=E$.
\end{theorem}
\begin{proof}
The action law gives $(ba)\cdot C=b\cdot(a\cdot C)=b\cdot D=E$.
\end{proof}

\begin{theorem}[Reversal]
If $a\cdot C=D$, then $a^{-1}\cdot D=C$.
\end{theorem}
\begin{proof}
Apply $a^{-1}$ and use $a^{-1}a=1$.
\end{proof}

\begin{definition}[Connector]
The connector $\kappa(C,D)$ is the unique element of $G$ satisfying $\kappa(C,D)\cdot C=D$. Existence follows from transitivity and uniqueness from freeness.
\end{definition}

\begin{theorem}[Connector recovery and uniqueness]
If $a\cdot C=D$, then $\kappa(C,D)=a$. Consequently, if both $a$ and $b$ verify the same step from $C$ to $D$, then $a=b$.
\end{theorem}
\begin{proof}
The connector and the advertised label have equal action on $C$, so freeness identifies them. Applying this to both labels proves uniqueness.
\end{proof}

\begin{corollary}[Finite chains]
For a chain
\[
C_0\xrightarrow{a_1}C_1\xrightarrow{a_2}\cdots\xrightarrow{a_n}C_n,
\]
the product $a_n\cdots a_1$ carries $C_0$ to $C_n$. Any two verified chains with the same endpoints have equal total products.
\end{corollary}
\begin{proof}
Induct using composition. Uniqueness identifies any two products connecting the same endpoints.
\end{proof}

\section{Applications and numerical checks}
The affine theorem supplies a direct postcondition for point evaluation. The exact-fiber result makes $x+x^{-1}$ an orbit descriptor for reciprocal inversion, with $x^2=1$ marking singleton orbits. The target factorization exposes ordinate-zero points for subsequent low-degree arithmetic. Radical normalization separates square-root extraction from ordinary quotient evaluation, and injectivity ensures that nonzero scaling itself creates no collisions. The action laws then provide an audit layer for chains: labels multiply, reverse by inversion, and are fixed by endpoints.

Over a prime field $\F_p$, one can reproducibly enumerate nonzero $x$, find ordinates satisfying $y^2=x^3+Ax^2+x$, and check source membership, target membership, deck invariance, and reciprocal fibers. A square table gives a simple $O(p)$ educational enumeration after $O(p)$ preprocessing. These finite checks illustrate rather than replace the field identities, and they are useful for catching modular-sign, inversion, and exceptional-input errors.

\section{Limitations and future work}
The rational formula should be extended to smooth projective curves in characteristic different from two, with a proof that it is a separable degree-two isogeny whose kernel is exactly the identity and $(0,0)$. After converting the target to Montgomery form, the quotient by the image two-torsion point should yield the dual map and compose with the first map to multiplication by two.

For nonsingular supersingular curves over $\F_{p^2}$, the quotient should preserve supersingularity and the number of rational points. If $r^2=s^2=B$ with nonzero radicals, the two normalization choices should be conjugate by $(X,Y)\mapsto(X,-Y)$ under appropriate characteristic assumptions. Finally, the finite-chain corollary should be integrated with concrete local evaluations to obtain a protocol-level chain certificate independent of intermediate curves.

\section{Conclusion}
The formulas $X=x+x^{-1}$ and $Y=y(1-x^{-2})$ define a completely controlled affine quotient on the nonzero chart of a normalized Montgomery curve. Their image equation, deck invariance, exact fibers, torsion-root behavior, and compatibility with radical normalization follow from direct field algebra. Free transitive group actions supply the complementary global laws for composition, reversal, and unique labels. Together these results form a self-contained foundation for radical degree-two evaluation and its use in chains of isogeny-class transitions.

