from __future__ import annotations

def inv(a: int, p: int) -> int:
    if a % p == 0:
        raise ZeroDivisionError("affine pole at x = 0")
    return pow(a, -1, p)

def evaluate(point: tuple[int, int], p: int) -> tuple[int, int]:
    x, y = point
    u = inv(x, p)
    return (x + u) % p, (y * (1 - u * u)) % p

def run(p: int = 101, a: int = 5) -> None:
    checked = 0
    for x in range(1, p):
        rhs = (x**3 + a*x*x + x) % p
        for y in range(p):
            if y*y % p != rhs:
                continue
            X, Y = evaluate((x, y), p)
            assert Y*Y % p == (X**3 + a*X*X - 4*X - 4*a) % p
            checked += 1
    print(f"Verified {checked} nonzero affine points over F_{p} for A={a}.")

if __name__ == "__main__":
    run()

from __future__ import annotations
from collections import defaultdict

def reciprocal_fibers(p: int) -> dict[int, list[int]]:
    fibers: dict[int, list[int]] = defaultdict(list)
    for x in range(1, p):
        fibers[(x + pow(x, -1, p)) % p].append(x)
    return dict(fibers)

def run(p: int = 101) -> None:
    fibers = reciprocal_fibers(p)
    for members in fibers.values():
        assert len(members) <= 2
        x = members[0]
        assert all(z == x or x*z % p == 1 for z in members)
    histogram = {size: sum(len(v) == size for v in fibers.values()) for size in (1, 2)}
    print(f"F_{p} fiber histogram: {histogram}")

if __name__ == "__main__":
    run()

from __future__ import annotations

def normalize_then_quotient(p: int, r: int, point: tuple[int, int]) -> tuple[int, int]:
    x, y = point
    if x % p == 0:
        raise ZeroDivisionError("affine pole")
    normalized_y = r*y % p
    u = pow(x, -1, p)
    return (x + u) % p, normalized_y*(1-u*u) % p

def run(p: int = 101, a: int = 5, r: int = 7) -> None:
    B = r*r % p
    for x in range(1, p):
        for y in range(p):
            if B*y*y % p != (x**3 + a*x*x + x) % p:
                continue
            X, Y = normalize_then_quotient(p, r, (x, y))
            assert Y*Y % p == (X**3 + a*X*X - 4*X - 4*a) % p
            print(f"B={B}, twisted point={(x,y)}, quotient={(X,Y)}")
            return
    raise RuntimeError("no example found")

if __name__ == "__main__":
    run()

