from __future__ import annotations
from enum import Enum

class FiberRelation(Enum):
    SAME = "same input"
    RECIPROCAL = "reciprocal pair"
    DISTINCT = "distinct fibers"

def classify_fiber(p: int, x: int, z: int) -> FiberRelation:
    if x % p == 0 or z % p == 0:
        raise ValueError("inputs must be nonzero")
    if x % p == z % p:
        return FiberRelation.SAME
    if x*z % p == 1:
        return FiberRelation.RECIPROCAL
    return FiberRelation.DISTINCT

